#!/usr/bin/env python3
"""Regenerates brotli.inc: Brotli streams made by the reference encoder
(pip install brotli), which Zepra's own decoder is tested against."""
import os, random, zlib
import brotli

random.seed(1)
text = (b"The quick brown fox jumps over the lazy dog. THE WORLD of the web, "
        b"and the time of the year. Information, specification, classification. ") * 6
html = (b"<!DOCTYPE html><html><head><title>Zepra</title></head><body>"
        b"<p class=\"intro\">Hello, world!</p><a href=\"https://example.com/\">link</a></body></html>") * 4
utf8 = "Привет, мир! Ελληνικά κείμενα. 日本語のテキスト。".encode() * 5
noise = bytes(random.getrandbits(8) for _ in range(3000))
cases = [
    ("kText", text, dict(quality=11, mode=brotli.MODE_TEXT)),
    ("kTextFast", text, dict(quality=1)),
    ("kHtml", html, dict(quality=9, lgwin=16)),
    ("kUtf8", utf8, dict(quality=11, mode=brotli.MODE_TEXT)),
    ("kNoise", noise, dict(quality=5)),  # incompressible: uncompressed meta-blocks
    ("kSmallWindow", text + html, dict(quality=11, lgwin=10)),
    ("kEmpty", b"", dict(quality=11)),
]

def arr(name, b):
    lines = ["    " + ", ".join("0x%02x" % x for x in b[i:i + 16]) + "," for i in range(0, len(b), 16)]
    return "const uint8_t %s[] = {\n%s\n};\n" % (name, "\n".join(lines))

out = ["// Generated by gen_brotli.py with the reference Brotli encoder. Do not edit.\n"]
out.append("struct BrotliCase { const char* name; const uint8_t* data; size_t size; uint32_t crc; size_t length; };\n")
for name, raw, opts in cases:
    out.append(arr(name, brotli.compress(raw, **opts)))
out.append("const BrotliCase kBrotliCases[] = {")
for name, raw, opts in cases:
    out.append('    {"%s", %s, sizeof(%s), 0x%08xu, %d},' % (name, name, name, zlib.crc32(raw), len(raw)))
out.append("};\n")
with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "brotli.inc"), "w") as f:
    f.write("\n".join(out))
